function UIFeelingShopDialog:FillSelf()
    CfUtils.FillText(self.CfText1, localize("合计"))
    CfUtils.FillText(self.TxtTime, localize("今日送礼次数："))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnPay))

    self.LoopRoleView:InitGridView(#self._allCats, Bind(self, self.OnGetRoleCellByIndex))
    self:SetCurState(STATE.NONE)

    self:RefeshNpcState(NPCSTATE.TYPE1)
end

function UIFeelingShopDialog:OnGetRoleCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allCats[index + 1]
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingShopRoleNode)
    if scr then
        scr:Refresh(id, index, function()
            self:OnSelectRole(index)
        end)
        if self._isFirst then
            scr:GiveGiftNumAnimator()
        end
        if self._roleAnim < 4 then
            scr:PlayAni1()
            self._roleAnim = self._roleAnim + 1
        end
    end
    return cell
end

--选择一个角色
function UIFeelingShopDialog:OnSelectRole(index)
    local catId = self._allCats[index + 1]
    local isCanGiveGift = PhoneUtils.IsCatCanGiveGift(catId)
    if not isCanGiveGift then
        GameUtils.Toast(localize("该角色今天已经送过礼物了"))
        return
    end

    self._curCatId = catId
    local data = phoneComp:GetCatDataById(self._curCatId)
    if not data then
        return
    end

    local scr = CfUtils.GetLuaScr(self.CurRoleGo, UIFeelingShopRoleNode)
    if scr then
        scr:Refresh(self._curCatId, nil, nil, function()
            self._curCatId = nil
            self._curGiftId = nil
            self._curPackId = nil
            self:SetCurState(STATE.NONE)
            self:RefeshNpcState(NPCSTATE.TYPE2)
            self:RefeshCurLikabilityExp()
        end)
        scr:ActiveBtnReset(true)
    end

    self:SetCurState(STATE.GIFT)
    self:RefeshNpcState(NPCSTATE.TYPE3)
end

--刷新选择礼物界面
function UIFeelingShopDialog:RefeshChooseGift()
    self._allGifts = PhoneUtils.GetCatCurSelectGifts(self._curCatId)
    if not self._allGifts then
        return
    end
    --self._giftAnim = 0

    if not self._isInitGiftView then
        self.LoopGiftsView:InitGridView(#self._allGifts, Bind(self, self.OnGetGiftCellByIndex))
        self._isInitGiftView = true
    else
        GameUtils.ReloadData(self.LoopGiftsView, #self._allGifts)
    end
end

function UIFeelingShopDialog:OnGetGiftCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allGifts[index + 1]
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingShopGiftNode)
    if scr then
        scr:Refresh(id, index, function()
            self:OnSelectGift(index)
        end)

        if self._giftAnim < 3 then
            scr:PlayAni1()
            self._giftAnim = self._giftAnim + 1
        else
            scr:ActiveRoot()
        end
    end
    return cell
end

--选择一个礼物
function UIFeelingShopDialog:OnSelectGift(index)
    self._curGiftId = self._allGifts[index + 1]
    self:RefeshCurLikabilityExp()
    local vo = PhoneUtils.GetPhoneGiftVo(self._curGiftId)
    if not vo then
        return
    end

    local scr = CfUtils.GetLuaScr(self.CurGift, UIFeelingShopGiftNode)
