            self:RefeshCurLikabilityExp()
        end)
        scr:ActiveBtnReset(true)
    end

    self:SetCurState(STATE.PACK)
    self:RefeshNpcState(NPCSTATE.TYPE4)
end

--刷新包装信息
function UIFeelingShopDialog:RefeshChoosePack()
    if not self.isInitPack then
        local t = CfUtils.GetCfTable(AutoIds.IdSetting868)
        if not t then
            return
        end
        self._allPacks = {}

        for k, v in pairs(t) do
            local id = v:Get("id")
            table.insert(self._allPacks, id)
        end 
        self.isInitPack = true
    end
    if not self._allPacks then
        return
    end

    if not self._isInitPackView then
        self.LoopPacksView:InitGridView(#self._allPacks, Bind(self, self.OnGetPackCellByIndex))
        self._isInitPackView = true
    else
        GameUtils.ReloadData(self.LoopPacksView, #self._allPacks)
    end
end

function UIFeelingShopDialog:OnGetPackCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local id = self._allPacks[index + 1]
    local cell = listView:NewListViewItem("Cell")
    local scr = CfUtils.GetLuaScr(cell, UIFeelingShopPackNode)
    if scr then
        scr:Refresh(id, self._curGiftId, index, function()
            self:OnSelectPack(index)
        end, nil)

        if self._packAnim < 3 then
            scr:PlayAni1()
            self._packAnim = self._packAnim + 1
        else
            scr:ActiveRoot()
        end
    end

    return cell
end

--选择一个包装
function UIFeelingShopDialog:OnSelectPack(index)
    self._curPackId = self._allPacks[index + 1]
    self:RefeshCurLikabilityExp()
    local vo = PhoneUtils.GetPhoneGiftPackUpVo(self._curPackId)
    if not vo then
        return
    end

    local scr = CfUtils.GetLuaScr(self.CurPack, UIFeelingShopPackNode)
    if scr then
        scr:Refresh(self._curPackId, self._curGiftId, nil, nil, function()
            self._curPackId = nil
            self:SetCurState(STATE.PACK)
            self:RefeshNpcState(NPCSTATE.TYPE4)
            self:RefeshCurLikabilityExp()
        end)
        scr:ActiveBtnReset(true)
    end
    
    self:SetCurState(STATE.PAY)
    self:RefeshPay()
    self:RefeshNpcState(NPCSTATE.TYPE5)
end

--刷新支付信息
function UIFeelingShopDialog:RefeshPay()
    local cost = 0
    --礼物的钱
    local vo = PhoneUtils.GetPhoneGiftGradeUpVo(self._curGiftId)
    if vo then
        cost = cost + checkNumber(vo.coinAmount)
    end
    --包装的钱
    local vo = PhoneUtils.GetPhoneGiftPackUpVo(self._curPackId)
    if vo then
        cost = cost + checkNumber(vo.coinAmount)
    end

    CfUtils.FillText(self.ConstNum, cost)
    local vo = PhoneUtils.GetPhoneGiftPackUpVo(self._curPackId)
    if vo then
        CfUtils.FillImage(self.PayGo.transform:Find("CombinedGroup/Buygroup/icon"), GoodsConfMgr:GetInstance():GetPhotoPathById(vo.coinId))
    end

    local dojo = PhoneUtils.GetCatDojoById(self._curCatId)
    if dojo then
        CfUtils.FillText(self.Txtnum, checkNumber(dojo.leftGiveGiftTimes))
    end
end

--刷新当前好感度
function UIFeelingShopDialog:RefeshCurLikabilityExp()
    local scr = CfUtils.GetLuaScr(self.CurRoleGo, UIFeelingShopRoleNode)
    if scr then
        scr:RefreshLikabilityExp(self._curCatId, self._curGiftId, self._curPackId)
    end
end

--支付
function UIFeelingShopDialog:OnBtnPay()
    if PhoneUtils.IsCatCanGiveGift(self._curCatId) then
        local allConsume = PhoneUtils.GetPhoneGiftConsume(self._curGiftId) + PhoneUtils.GetPhonePackConsume(self._curPackId)
        if GoodsUtils.GetThingNo(Constants.Currency.PhoneShop) < allConsume then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.PhoneShop)
            if vo then
                GameUtils.Toast(vo.name..localize("数量不足"))
            end
            return
        end

        phoneComp:PhoneGiveGiftReq(self._curCatId, self._curGiftId, self._curPackId, function(oldLevel, newLevel)
            GoodsUtils.DrawRewards({
                { goodsId = Constants.Currency.PhoneShop, num = -allConsume}
            })
            GameUtils.UpdateNavBarShowGoods({Constants.Currency.PhoneShop})
            self:OnGiveGiftSuccess(oldLevel, newLevel)
        end)
    else
        GameUtils.Toast(localize("今日送礼次数不足"))
    end
end

--送礼成功
function UIFeelingShopDialog:OnGiveGiftSuccess(oldLevel, newLevel)
    KTool.SetActive(self.RightPanel, false)
    SetButtonAction(self.BtnResult, function()
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingShopOpenPresentsDialog, parameters = {catId = self._curCatId, giftId = self._curGiftId, giftPackId = self._curPackId, oldLevel = oldLevel, newLevel = newLevel}}, {
            {id = Constants.UITypeIds.UIFeelingShopDialog}
        })
    end)
    self:RefeshNpcState(NPCSTATE.TYPE6)
end

--设置当前状态
function UIFeelingShopDialog:SetCurState(state)
    self:ReplayStatus(state)
    if state == STATE.NONE then
        local co = cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(0.1))
            --self:RefeshChooseGift()
        end)
        table.insert(self._cos, co)
    elseif state == STATE.GIFT then
        local co = cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(0.1))
            self:RefeshChooseGift()
        end)
        table.insert(self._cos, co)
    elseif state == STATE.PACK then
        local co = cs_coroutine.start(function()
            coroutine.yield(WaitForSeconds(0.1))
            self:RefeshChoosePack()
        end)
        table.insert(self._cos, co)
    elseif state == STATE.PAY then
        local co = cs_coroutine.start(function()
            KTool.SetActive(self.CurPack, false)
            KTool.SetActive(self.PayGo, false)
            KTool.SetActive(self.CurPack, true)
            coroutine.yield(WaitForSeconds(0.1))
            KTool.SetActive(self.PayGo, true)
        end)
        table.insert(self._cos, co)
    end
end

function UIFeelingShopDialog:ReplayStatus(state)
    local sliderGift = self.CurRoleGo.transform:Find("sliderGift"):GetComponent("Slider")
    local sliderPack = self.CurRoleGo.transform:Find("sliderPack"):GetComponent("Slider")

    KTool.SetActive(self.LoopRoleView, state == STATE.NONE)
    KTool.SetActive(self.SelectGiftPack, state ~= STATE.NONE)

    KTool.SetActive(self.LoopGiftsView, state == STATE.GIFT)

    KTool.SetActive(self.CurGift, state == STATE.PACK or state == STATE.PAY)
    KTool.SetActive(sliderGift, state == STATE.PACK or state == STATE.PAY)
    KTool.SetActive(self.LoopPacksView, state == STATE.PACK)

    KTool.SetActive(self.CurPack, state == STATE.PAY)
    KTool.SetActive(sliderPack, state == STATE.PAY)
    KTool.SetActive(self.PayGo, state == STATE.PAY)
end

function UIFeelingShopDialog:RefeshNpcState(state)
    if self._npcSpinCo then
        cs_coroutine.stop(self._npcSpinCo)
        self._npcSpinCo = nil
    end

    if not self._catGo then
        return
    end
    self._npcSpinCo = cs_coroutine.start(function()
        --CfUtils.FillText(self.NpcTalk, talk)
        if state == NPCSTATE.TYPE1 then
            local canvas = self.LoopRoleView.transform.parent:GetComponent(typeof(CanvasGroup))
            if canvas then
                --播放动画时屏蔽点击
                canvas.blocksRaycasts = false
            end
            CfUtils.PlayAnimator(self._catGo, "idle_begin")
            self:RefeshNpcTalk(NPCSTATE.TYPE1)
            coroutine.yield(WaitForSeconds(CfUtils.GetAnimatorTime(self._catGo, "idle_begin")))
            self._isFirst = false
            --[[
            CfUtils.PlayAnimator(self._catGo, "idle_give", true)
            ]]
            self:RefeshNpcTalk(NPCSTATE.TYPE2)
            if canvas then
                canvas.blocksRaycasts = true
            end
        elseif state == NPCSTATE.TYPE2 then
            CfUtils.PlayAnimator(self._catGo, "idle_give", true)
            self:RefeshNpcTalk(NPCSTATE.TYPE2)
        elseif state == NPCSTATE.TYPE3 then
            CfUtils.PlayAnimator(self._catGo, "idle_recommend", true)
            self:RefeshNpcTalk(NPCSTATE.TYPE3)
        elseif state == NPCSTATE.TYPE4 then
            CfUtils.PlayAnimator(self._catGo, "idle_choice", true)
            self:RefeshNpcTalk(NPCSTATE.TYPE4)
        elseif state == NPCSTATE.TYPE5 then
            CfUtils.PlayAnimator(self._catGo, "idle_price", true)
            self:RefeshNpcTalk(NPCSTATE.TYPE5)
        elseif state == NPCSTATE.TYPE6 then
            CfUtils.PlayAnimator(self._catGo, "idle_send")
            self:RefeshNpcTalk(NPCSTATE.TYPE6)
            coroutine.yield(WaitForSeconds(CfUtils.GetAnimatorTime(self._catGo, "idle_send")))
            self:RefeshNpcTalk(NPCSTATE.TYPE7)
            KTool.SetActive(self.BtnResult, true)
        end
    end)
end 

function UIFeelingShopDialog:RefeshNpcTalk(state)
    if self._npcTalkCo then
        cs_coroutine.stop(self._npcTalkCo)
        self._npcTalkCo = nil
    end
    self._npcTalkCo = cs_coroutine.start(function()
        if self.isTalking then 
            self.Imgbg:Play("FeelingShopDialogNpcTalkOff")
            coroutine.yield(WaitForSeconds(CfUtils.GetAnimatorTime(self.Imgbg, "FeelingShopDialogNpcTalkOff")))
        end
        local talk = ""
        local npcVo = PhoneUtils.GetPhoneShopNpcVo(state)
        if npcVo then
            talk = npcVo.text
            CfUtils.FillText(self.NpcTalk, talk)
            CfUtils.FillText(self.Name, npcVo.title)
        end
        self.Imgbg:Play("FeelingShopDialogNpcTalkOn")
        self.isTalking = true
        coroutine.yield(WaitForSeconds(10))
        self.isTalking = false
    end)
end

--月卡到期
function UIFeelingShopDialog:OnMonthCardStop()
    PhoneUtils.UpdateGiveGiftNum(false)
    GameUtils.ReloadData(self.LoopRoleView, #self._allCats)
end

function UIFeelingShopDialog:OnMonthCardRefresh()
    if self._isHasMonthCard then
        return
    end
    PhoneUtils.UpdateGiveGiftNum(true)
    GameUtils.ReloadData(self.LoopRoleView, #self._allCats)
end

function UIFeelingShopDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KTool.SetActive(self.RawImage, false)
        phoneComp:EnterPhoneHomeReq(function()
            CfUtils.SetUICameraProjection(false)
            CfUtils.SetTopCommonActive(true, true)
            GameUtils.UpdateNavBarShowGoods({Constants.Currency.PhoneShop})
    
            --模型
            self._loader = CS.Engine.Modules.ResourceModule.LoadBundleSync(CatGeneralShopPath, nil, true)
            if self._loader.IsSuccess then
                self._catGeneralGo = CfUtils.InstantiateGo(self._loader.ResultObject)
                self._catGeneralGo.transform.position = Vector3(200, 1000, 0)
            end        
            
            local path = PhoneUtils.GetCatGeneralPath()
            if not string.isEmpty(path) then
                self._catLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync(path, nil, true)
            end
            if self._catLoader.IsSuccess then
                self._catGo = CfUtils.InstantiateGo(self._catLoader.ResultObject, self._catGeneralGo.transform:Find("CatPar"))
            end   
    
            if self._catGeneralGo then
                self._cam = self._catGeneralGo.transform:Find("CatGeneralCamera"):GetComponent("Camera")
            end
            self._renderTexture = CS.UnityEngine.RenderTexture.GetTemporary(2048, 2048, 0, CS.UnityEngine.RenderTextureFormat.Default);
            self._cam.targetTexture = self._renderTexture
            KTool.SetActive(self.RawImage, true)
            self.RawImage.texture = self._renderTexture

            local _allCats = PhoneUtils.GetAllUnlockCatIdArray()
            table.sort(_allCats, function(a, b)
                return (not PhoneUtils.IsCatCanGiveGift(b) and PhoneUtils.IsCatCanGiveGift(a))
            end)
            self._allCats = _allCats
            
            self:FillSelf()
        end)
    end))
    return coWait
end

function UIFeelingShopDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self) then
            if self._npcSpinCo then
                cs_coroutine.stop(self._npcSpinCo)
                self._npcSpinCo = nil
            end
            if self._npcTalkCo then
                cs_coroutine.stop(self._npcTalkCo)
                self._npcTalkCo = nil
            end
            if self._cos then
                for k, v in pairs(self._cos) do
                    cs_coroutine.stop(v)
                end
            end
            if self._loader then
                self._loader:Release()
                self._loader = nil
            end
            if self._catLoader then
                self._catLoader:Release()
                self._catLoader = nil
            end
            if self._renderTexture then
                self._renderTexture:Release()
            end
            Events.RemoveListener(Constants.EventNames.OnMonthCardRefresh, self.EventMonthCardRefresh)
            Events.RemoveListener(Constants.EventNames.OnMonthCardExpired, self.EventMonthCardStop)
            if self._catGo then
                KTool.SafeDelete(self._catGo)
            end
            if self._catGeneralGo then
                KTool.SafeDelete(self._catGeneralGo)
            end
        end
        GameUtils.UpdateNavBarShowGoods()
        --CfUtils.SetTopCommonActive(false, false)
        CfUtils.SetUICameraProjection(true)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFeelingShopDialog
